523	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
524	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
525	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
526	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
527	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
528		handoverID = clean(handoverID)
529		itemID = clean(itemID)
530		operator = clean(operator)
531		reason = clean(reason)
532		trackingNote = clean(trackingNote)
533		nextFollowOwner = clean(nextFollowOwner)
534	
535		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
536			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
537		}
538		if err := requireNonEmpty("操作人", operator); err != nil {
539			return Handover{}, err
540		}
541	
542		var result Handover
543		err := svc.store.mutate(func(d *Data) error {
544			h, _ := findHandover(d, handoverID)
545			if h == nil {
546				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
547			}
548			e, _ := findEntry(h, itemID)
549			if e == nil {
550				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
551			}
552			if e.Status.Received() {
553				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
554					ErrHandoverState, e.ItemID, e.Status.Label())
555			}
556			if e.Status == EntryReturned {
557				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
558				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
559				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
560				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
561					ErrHandoverState, e.ItemID, h.ID)
562			}
563			switch action {
564			case ActionReturn:
565				if err := requireNonEmpty("退回原因", reason); err != nil {
566					return err
567				}
568			case ActionTrack:
569				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
570					return err
571				}
572				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
573					return err
574				}
575			}
576	
577			now := svc.now()
578			switch action {
579			case ActionConfirm:
580				e.Status = EntryConfirmed
581			case ActionTrack:
582				e.Status = EntryTracking
583				e.TrackingNote = trackingNote
584				e.FollowOwner = nextFollowOwner
585			case ActionReturn:
586				e.Status = EntryReturned
587				e.Rounds = append(e.Rounds, ReturnRound{
588					Seq:            len(e.Rounds) + 1,
589					ReturnedAt:     now,
590					ReturnOperator: operator,
591					Reason:         reason,
592				})
593			}
594			e.Operator = operator
595			e.ProcessedAt = &now
596	
597			if action != ActionReturn {
598				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
599				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
600					it.CurrentShiftID = h.ToShiftID
601					if !contains(it.ShiftIDs, h.ToShiftID) {
602						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
603					}
604					detail := "接班班次 " + h.ToShiftID + " 接收：" + e.Status.Label()
605					if action == ActionTrack {
606						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
607						it.FollowOwner = nextFollowOwner
608						detail += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
609					}
610					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
611				}
612			}
613	
614			if h.Completed() && h.CompletedAt == nil {
615				h.CompletedAt = &now
616			}
617			result = *h
618			return nil
619		})
620		return result, err
621	}
622	
623	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
624	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
625	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
626	
627	func contains(xs []string, x string) bool {
628		for _, v := range xs {
629			if v == x {
630				return true
631			}
632		}
633		return false
634	}
635	
636	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
637	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
638	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
639	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
640	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
641	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
642	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
643		handoverID = clean(handoverID)
644		itemID = clean(itemID)
645		operator = clean(operator)
646		supplement = clean(supplement)
647		if err := requireNonEmpty("操作人", operator); err != nil {
648			return Handover{}, err
649		}
650		if err := requireNonEmpty("补充说明", supplement); err != nil {
651			return Handover{}, err
652		}
653	
654		var result Handover
655		err := svc.store.mutate(func(d *Data) error {
656			h, _ := findHandover(d, handoverID)
657			if h == nil {
658				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
659			}
660			e, _ := findEntry(h, itemID)
661			if e == nil {
662				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
663			}
664			if e.Status != EntryReturned {
665				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
666					ErrHandoverState, e.ItemID, e.Status.Label())
667			}
668			if len(e.Rounds) == 0 {
669				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
670			}
671			round := &e.Rounds[len(e.Rounds)-1]
672			if round.ResubmittedAt != nil {
673				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
674			}
675			now := svc.now()
676			round.Supplement = supplement
677			round.SupplementOperator = operator
678			round.SupplementAt = &now
679			round.ResubmittedAt = &now
680			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
681			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
682			e.Status = EntryPending
683			e.Operator = ""
684			e.ProcessedAt = nil
685			result = *h
686			return nil
687		})
688		return result, err
689	}
